package com.shopstream.demo;

import java.util.List;
import org.springframework.data.redis.core.RedisCallback;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
public class PipelineDemo {

    private final StringRedisTemplate redis;
    public PipelineDemo(StringRedisTemplate redis) {
        this.redis = redis;
    }

    public List<Object> loadStock(List<String> skus) {
        RedisCallback<Object> batch = connection -> {
            for (String sku : skus) {
                connection.stringCommands().get(("stock:" + sku).getBytes());
            }
            return null;
        };
        return redis.executePipelined(batch);
    }
}
